const $=s=>document.querySelector(s);const labels={news:'實用情報',event:'活動手帳',meme:'校園梗庫'};const words={news:'生活備忘',event:'留一天',meme:'懂的都懂'};let posts=[],places=[],filter='all';
function el(tag,text,cls){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e}
function link(text,url){const a=el('a',text);a.href=url;return a}
function safeURL(url){try{const u=new URL(url);return ['https:','http:'].includes(u.protocol)?u.href:null}catch{return null}}
function eventState(p){if(!p.eventStart)return '';const now=Date.now(),start=Date.parse(p.eventStart),end=Date.parse(p.eventEnd||p.eventStart);return now>end?'已結束':now>=start?'進行中':'即將開始'}
function render(){const q=$('#search').value.trim().toLowerCase();const shown=posts.filter(p=>(filter==='all'||(filter==='archive'?p.contentType==='archive':p.category===filter))&&[p.title,p.summary,...p.tags,...p.placeIds.map(id=>places.find(x=>x.id===id)?.name||'')].join(' ').toLowerCase().includes(q));$('#cards').replaceChildren();$('#count').textContent=`共 ${shown.length} 則日常`;for(const p of shown){const a=link('',`article.html?id=${encodeURIComponent(p.id)}`);a.className='card';const cover=el('div',undefined,'cover '+p.category);cover.setAttribute('aria-hidden','true');cover.append(el('span',words[p.category],'cover-word'),el('small',p.contentType==='source-index'?'SOURCE / TO BE COMPLETED':p.category==='meme'?'CAMPUS / MEME ARCHIVE':'CAMPUS / NOTES'));const meta=el('div',undefined,'meta');meta.append(el('span',labels[p.category]+(p.category==='event'?' · '+eventState(p):'')),el('span',p.sourcePeriod?`來源 ${p.sourcePeriod}`:p.contentType==='source-index'?'待補脈絡':'來源日期未詳'));const read=el('span',undefined,'read');read.append(el('span','閱讀手記'),el('span','↗'));a.append(cover,meta,el('h3',p.title),el('p',p.summary),read);$('#cards').append(a)}if(!shown.length)$('#cards').append(el('p','沒有找到符合的日常，換個關鍵字試試。'))}
function showArticle(id){$('#home').hidden=true;$('#article').hidden=false;const root=$('#article'),p=posts.find(x=>x.id===id);root.replaceChildren(link('← 回到校園手記','index.html#journal'));if(!p){root.append(el('h1','這篇手記還沒找到'),el('p','可能連結有誤，請回首頁選擇文章。'));return}document.title=p.title+' — 燕巢日常';root.append(el('p',labels[p.category]+(p.category==='event'?' · '+eventState(p):''),'eyebrow'),el('h1',p.title),el('p',`發布 ${p.publishedAt} / 更新 ${p.updatedAt}`,'fine'),el('p',p.summary,'lead'));if(p.contentKind==='source-index')root.append(el('p','來源索引／原文未完整取得，尚不作為事件事實。','tag'));if(p.contentKind==='community')root.append(el('p','社群紀錄／確認有此討論，不等於事件已獨立查證。','tag'));if(p.contentKind==='fiction')root.append(el('p','原創虛構／幽默創作，非新聞或已查證的校園傳聞。','tag'));const body=el('div',undefined,'body');p.body.forEach(t=>body.append(el('p',t)));root.append(body);if(p.eventStart){root.append(el('p',`活動時間：${p.eventStart.slice(0,16).replace('T',' ')} ～ ${p.eventEnd.slice(11,16)}（臺灣時間）`),el('p',`地點：${p.location}`),el('p','報名狀態未確認；截止日期未提供。請向主辦單位確認。'));const url=safeURL(p.registrationUrl);if(url)root.append(link('查看主辦單位報名表 ↗',url))}if(p.placeIds.length)root.append(el('p','相關地點：'+p.placeIds.map(id=>places.find(x=>x.id===id)?.name||id).join('、')));if(p.evidenceNote)root.append(el('p','讀取與查證範圍：'+p.evidenceNote,'evidence-note'));if(p.simulatorUse)root.append(el('p','模擬器素材備註：'+p.simulatorUse,'fine'));const box=el('aside',undefined,'source-box');box.append(el('strong',p.sources.length?'來源與查閱紀錄':'創作與使用說明'));for(const s of p.sources){const u=safeURL(s.url);if(u)box.append(link(s.title+' ↗',u));box.append(el('p',`原文日期：${s.publishedAt||'未確認'} · 查閱／嘗試讀取：${s.accessedAt}`))}box.append(el('p',p.rights.text),el('p',p.rights.sourceMedia));root.append(box)}
async function init(){try{const responses=await Promise.all(['data/posts.json','data/places.json'].map(url=>fetch(url)));if(responses.some(r=>!r.ok))throw Error('load');const [a,b]=await Promise.all(responses.map(r=>r.json()));posts=a.posts.filter(p=>p.status==='published').sort((a,b)=>b.publishedAt.localeCompare(a.publishedAt)||a.id.localeCompare(b.id));places=b.places;for(const place of places){const btn=el('button',undefined,'place-button');btn.setAttribute('aria-pressed','false');btn.append(el('strong',place.name+' ↗'),el('small',place.description));btn.onclick=()=>{document.querySelectorAll('.place-button').forEach(b=>b.setAttribute('aria-pressed',String(b===btn)));const r=$('#place-stories');r.replaceChildren(el('p',place.name+'的相關手記'));posts.filter(p=>p.placeIds.includes(place.id)).forEach(p=>r.append(link(p.title,`article.html?id=${encodeURIComponent(p.id)}`)))};$('#place-list').append(btn)}document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));render()});$('#search').addEventListener('input',render);const id=new URLSearchParams(location.search).get('id');if(id||location.pathname.endsWith('article.html'))showArticle(id);else render()}catch(e){$('#cards').replaceChildren(el('p','暫時無法讀取手記。請確認網站連線後重新整理。'));if(location.pathname.endsWith('article.html')){$('#home').hidden=true;$('#article').hidden=false;$('#article').replaceChildren(el('h1','暫時無法讀取文章'),link('返回首頁','index.html'))}}}init();
